/* Módulo Profundo: Investigation Store (State Manager) */
class InvestigationStore {
  constructor(initialState) {
    this.state = initialState;
    this.listeners = new Set();
    this.fileHandle = null;
    this.saveTimeout = null;
  }

  getState() {
    return this.state;
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  notify() {
    this.listeners.forEach(l => l(this.state));
    this.persist();
  }

  // Ações Semânticas
  addEquipeMember(member) {
    this.state.equipe.push(member);
    this.notify();
  }

  delEquipeMember(index) {
    this.state.equipe.splice(index, 1);
    this.notify();
  }

  // Mutador genérico para facilitar a migração do legado
  mutate(updater) {
    updater(this.state);
    this.notify();
  }

  // File System Access API
  async enableFileSystemSync() {
    try {
      const handle = await window.showSaveFilePicker({
        suggestedName: 'investigacao_faciu.json',
        types: [{
          description: 'Arquivo JSON do FACIU',
          accept: {'application/json': ['.json']},
        }],
      });
      this.fileHandle = handle;
      this.persist(); // Força um save inicial
      return true;
    } catch (err) {
      if (err.name !== 'AbortError') {
        console.error('Falha ao obter permissão de arquivo:', err);
      }
      return false;
    }
  }

  persist() {
    // 1. Fallback LocalStorage (Legado)
    try {
      localStorage.setItem(STORE, JSON.stringify(this.state));
    } catch(e) {
      const cheio = e && (e.name==='QuotaExceededError' || e.code===22 || e.code===1014);
      console.error('[FACIU] Falha ao salvar no navegador.',e);
      if(cheio && !window.__faciuQuotaAvisado){
        window.__faciuQuotaAvisado=true;
        alert('O armazenamento do navegador está cheio.\n\nO estudo NÃO foi salvo. Exporte o JSON agora.');
      }
    }

    // 2. Persistência Contínua via File System Access API
    if (!this.fileHandle) return;
    
    clearTimeout(this.saveTimeout);
    this.saveTimeout = setTimeout(async () => {
      try {
        const pkg = {
          fileType: 'brava-investigacao-causas',
          schemaVersion: '1.1',
          appVersion: APP_VERSION,
          exportedAt: new Date().toISOString(),
          study: this.state
        };
        const writable = await this.fileHandle.createWritable();
        await writable.write(JSON.stringify(pkg, null, 2));
        await writable.close();
        console.log('[FACIU] Sincronizado com o disco.');
      } catch (err) {
        console.error('[FACIU] Falha na gravação contínua no disco:', err);
      }
    }, 1000);
  }
}

async function enableDiskSync(btn) {
  if (!window.showSaveFilePicker) {
    alert("Seu navegador não suporta gravação contínua no disco. Use o Chrome ou Edge no computador.");
    return;
  }
  
  const success = await store.enableFileSystemSync();
  if (success) {
    btn.classList.add("text-lime-300");
    btn.innerHTML = '<i class="w-4 h-4" data-lucide="check-circle"></i><span class="hidden md:inline">Sincronizando</span>';
    lucide.createIcons();
    toast("Gravação contínua ativada. O arquivo será salvo a cada alteração.");
  }
}

/* REGION: AI ASSISTANT */
const DEFAULT_AI_PROMPT = `Você é um auditor sênior de segurança industrial especializado em RCA (Root Cause Analysis).
REGRA 1: NUNCA mencione IDs (ex: n_mtd...), códigos técnicos de grafos, portas lógicas (AND/OR/NONE), arrays JSON ou jargões de programação.
REGRA 2: Refira-se aos eventos e causas estritamente pelos seus textos (O Quê / Por Quê) informados pelo humano.
REGRA 3: Identifique APENAS contradições factuais graves:
  - Eventos na árvore que contradizem a ordem ou os fatos da cronologia.
  - Causas-raiz apontadas sem contexto suficiente.
  - Erros de causa e efeito gritantes (ex: uma consequência vindo antes da causa).
REGRA 4: Responda em Português de forma clara, didática e executiva, em formato de tópicos (bullet points).
REGRA 5: Faça uma checagem cruzada holística: As ações propostas mitigam as causas raiz apontadas? A gravidade da Triagem condiz com os danos do RIA?
Se não houver erros evidentes, responda com uma frase afirmativa atestando a coerência sistêmica.`;

const FaciuConfig = {
    KEYS: {
        HIDE_AI: 'faciu_hide_ai',
        AI_URL: 'faciu_ai_url',
        GROQ_KEY: 'faciu_groq_api_key',
        GROQ_MODEL: 'faciu_groq_model',
        AI_PROMPT: 'faciu_ai_prompt'
    },
    
    get(key, defaultValue = null) {
        const val = localStorage.getItem(key);
        return val !== null ? val : defaultValue;
    },
    
    set(key, value) {
        localStorage.setItem(key, value);
    },
    
    getBoolean(key, defaultValue = false) {
        const val = this.get(key);
        if (val === null) return defaultValue;
        return val === 'true';
    },
    
    applyVisibility() {
        const isHidden = this.getBoolean(this.KEYS.HIDE_AI, true);
        // Se nunca foi configurado, grava o default como true
        if (this.get(this.KEYS.HIDE_AI) === null) {
            this.set(this.KEYS.HIDE_AI, 'true');
        }
        document.body.classList.toggle('hide-ai-panel', isHidden);
    }
};

// Aplica a visibilidade imediatamente ao avaliar o script
FaciuConfig.applyVisibility();

window.configurarIA = function() {
    const modal = document.getElementById('aiConfigModal');
    
    document.getElementById('aiConfigHide').checked = FaciuConfig.getBoolean(FaciuConfig.KEYS.HIDE_AI, true);
    const savedUrl = FaciuConfig.get(FaciuConfig.KEYS.AI_URL, "https://api.groq.com/openai/v1/chat/completions");
    
    const providerSelect = document.getElementById('aiConfigProvider');
    const options = Array.from(providerSelect.options).map(o => o.value);
    if(options.includes(savedUrl)) {
        providerSelect.value = savedUrl;
    } else {
        providerSelect.value = 'custom';
    }
    document.getElementById('aiConfigUrl').value = savedUrl;
    if(window.aiConfigProviderChange) window.aiConfigProviderChange();
    
    document.getElementById('aiConfigKey').value = FaciuConfig.get(FaciuConfig.KEYS.GROQ_KEY, "");
    document.getElementById('aiConfigModel').value = FaciuConfig.get(FaciuConfig.KEYS.GROQ_MODEL, "llama-3.3-70b-versatile");
    document.getElementById('aiConfigPrompt').value = FaciuConfig.get(FaciuConfig.KEYS.AI_PROMPT, DEFAULT_AI_PROMPT);
    
    document.getElementById('aiConfigModelSelect').classList.add('hidden');
    document.getElementById('aiConfigModelError').classList.add('hidden');
    
    modal.hidden = false;
};

window.aiConfigProviderChange = function() {
    const p = document.getElementById('aiConfigProvider').value;
    const urlGroup = document.getElementById('aiConfigUrlGroup');
    const urlInput = document.getElementById('aiConfigUrl');
    
    if (p === 'custom') {
        urlGroup.style.display = 'block';
    } else {
        urlGroup.style.display = 'none';
        urlInput.value = p;
    }
};

window.closeAiConfigModal = function() {
    document.getElementById('aiConfigModal').hidden = true;
};

window.resetAiPrompt = function() {
    document.getElementById('aiConfigPrompt').value = DEFAULT_AI_PROMPT;
};

window.saveAiConfigModal = function() {
    const hideAi = document.getElementById('aiConfigHide').checked;
    const url = document.getElementById('aiConfigUrl').value.trim();
    const key = document.getElementById('aiConfigKey').value.trim();
    const model = document.getElementById('aiConfigModel').value.trim();
    const prompt = document.getElementById('aiConfigPrompt').value.trim();
    
    FaciuConfig.set(FaciuConfig.KEYS.HIDE_AI, hideAi ? 'true' : 'false');
    if (url) FaciuConfig.set(FaciuConfig.KEYS.AI_URL, url);
    if (key) FaciuConfig.set(FaciuConfig.KEYS.GROQ_KEY, key);
    if (model) FaciuConfig.set(FaciuConfig.KEYS.GROQ_MODEL, model);
    if (prompt) FaciuConfig.set(FaciuConfig.KEYS.AI_PROMPT, prompt);
    
    FaciuConfig.applyVisibility();
    closeAiConfigModal();
};

window.aiConfigFetchModels = async function() {
    const btn = document.getElementById('aiConfigFetchBtn');
    const select = document.getElementById('aiConfigModelSelect');
    const errDiv = document.getElementById('aiConfigModelError');
    const key = document.getElementById('aiConfigKey').value.trim();
    let url = document.getElementById('aiConfigUrl').value.trim();
    
    if (!key) {
        errDiv.textContent = "Insira a chave de API primeiro.";
        errDiv.classList.remove('hidden');
        return;
    }
    
    url = url.replace('/chat/completions', '/models');
    
    btn.disabled = true;
    btn.innerHTML = '<i class="w-4 h-4 animate-spin" data-lucide="loader"></i>';
    if(window.lucide) lucide.createIcons();
    
    try {
        const res = await fetch(url, { headers: { "Authorization": `Bearer ${key}` } });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        
        let models = data.data || [];
        models.sort((a,b) => a.id.localeCompare(b.id));
        
        select.innerHTML = '<option value="">-- Selecione um modelo --</option>' + models.map(m => `<option value="${m.id}">${m.id}</option>`).join('');
        select.classList.remove('hidden');
        errDiv.classList.add('hidden');
        
    } catch(err) {
        errDiv.textContent = "Erro ao buscar modelos. Verifique a chave ou provedor.";
        errDiv.classList.remove('hidden');
        select.classList.add('hidden');
    } finally {
        btn.disabled = false;
        btn.innerHTML = '<i class="w-4 h-4" data-lucide="download"></i> Buscar';
        if(window.lucide) lucide.createIcons();
    }
};

const FACIUAssistant = {
  isChecking: false,
  async checkSupport() {
    if (window.ai && window.ai.languageModel) {
      try {
        const cap = await window.ai.languageModel.capabilities();
        if (cap.available !== 'no') return 'nano';
      } catch(e) {}
    }
    const apiKey = FaciuConfig.get(FaciuConfig.KEYS.GROQ_KEY);
    if (apiKey) return 'groq';
    return null;
  },
  
  async startAudit() {
    if (this.isChecking) return;
    
    if (FaciuConfig.getBoolean(FaciuConfig.KEYS.HIDE_AI, true)) {
        alert("O painel da IA está desativado nas configurações.");
        return;
    }
    
    this.isChecking = true;
    const statusDiv = document.getElementById('aiAuditorStatus');
    const resultsDiv = document.getElementById('aiAuditorResults');
    
    statusDiv.innerHTML = '<span class="text-[12px] muted flex items-center gap-2"><i class="w-4 h-4 animate-spin" data-lucide="loader"></i> O Auditor IA está analisando a estrutura...</span>';
    if(window.lucide) lucide.createIcons({root: statusDiv});
    resultsDiv.classList.add('hidden');
    
    try {
      let support = await this.checkSupport();
      
      if (!support) {
        if (confirm("O motor Gemini Nano do Chrome não está disponível.\n\nDeseja configurar uma API externa na nuvem (OpenAI, OpenRouter, Groq, etc) agora?")) {
           window.configurarIA();
           this.isChecking = false;
           statusDiv.innerHTML = `<button type="button" class="btn btn-primary" onclick="FACIUAssistant.startAudit()"><i class="w-4 h-4" data-lucide="play"></i> Iniciar Auditoria</button>`;
           if(window.lucide) lucide.createIcons({root: statusDiv});
           return;
        } else {
           throw new Error('Chave de API não configurada. A auditoria de IA não pode ser executada.');
        }
      }
      
      const cleanTreeNodes = (state.tree?.nodes || []).map(n => ({
          tipo: n.kind,
          o_que_ocorreu: n.what || n.label,
          por_que_ocorreu: n.why || ""
      }));
      
      
      let riaData = null;
      try { riaData = window.faciuRia?.obj?.(); } catch(e) {}
      
      const payload = {
        triagem: state.triagem ? {
           titulo: state.triagem.titulo,
           categoria: state.triagem.categoria,
           metodos: state.triagem.metodos
        } : null,
        arvore_de_causas_limpa: cleanTreeNodes,
        cronologia: (state.chronology || []).map(c => ({
            data_hora: c.datetime, 
            descricao: c.description
        })),
        plano_de_acao: (state.acoes || []).map(a => ({
            o_que: a.oque,
            quem: a.quem,
            quando: a.quando,
            causas_raiz_relacionadas: a.causaRaizIds
        })),
        verificacao_eficacia: state.verificacaoEficacia ? {
            status: state.verificacaoEficacia.status,
            justificativa: state.verificacaoEficacia.justificativa
        } : null,
        dados_relatorio_ria: riaData ? {
            descricao_incidente: riaData.initialData?.description,
            data_incidente: riaData.initialData?.incidentDate,
            instalacao: riaData.installation?.name
        } : null
      };
    
      
      const systemPrompt = FaciuConfig.get(FaciuConfig.KEYS.AI_PROMPT, DEFAULT_AI_PROMPT);
      const promptText = `Avalie estes dados fornecidos pelo investigador:\n${JSON.stringify(payload)}`;

      let responseText = "";
      
      if (support === 'nano') {
        const session = await window.ai.languageModel.create({
          systemPrompt: systemPrompt
        });
        responseText = await session.prompt(promptText);
      } else if (support === 'groq') {
        const apiKey = FaciuConfig.get(FaciuConfig.KEYS.GROQ_KEY);
        const aiUrl = FaciuConfig.get(FaciuConfig.KEYS.AI_URL, "https://api.groq.com/openai/v1/chat/completions");
        const aiModel = FaciuConfig.get(FaciuConfig.KEYS.GROQ_MODEL, "llama-3.3-70b-versatile");
        
        const res = await fetch(aiUrl, {
          method: "POST",
          headers: {
             "Authorization": `Bearer ${apiKey}`,
             "Content-Type": "application/json",
             "HTTP-Referer": "http://localhost",
             "X-Title": "FACIU Auditor"
          },
          body: JSON.stringify({
            model: aiModel,
            messages: [
               {role: "system", content: systemPrompt},
               {role: "user", content: promptText}
            ],
            temperature: 0.1
          })
        });
        if (!res.ok) {
           const errData = await res.json().catch(()=>({}));
           throw new Error(errData.error?.message || `Erro da API Externa: ${res.status}`);
        }
        const data = await res.json();
        responseText = data.choices[0].message.content;
      }
      
      this.displayResults(responseText || "Nenhuma inconsistência detectada pela IA.");
      
    } catch (err) {
      this.displayResults(`Erro na auditoria: ${err.message}`, true);
    } finally {
      this.isChecking = false;
      let btnHtml = `<button type="button" class="btn btn-primary" onclick="FACIUAssistant.startAudit()"><i class="w-4 h-4" data-lucide="refresh-cw"></i> Refazer Auditoria</button>`;
      btnHtml += `<button type="button" class="btn btn-ghost ml-2" onclick="window.configurarIA();"><i class="w-4 h-4" data-lucide="settings"></i> Configurações de IA</button>`;
      statusDiv.innerHTML = btnHtml;
      if(window.lucide) lucide.createIcons({root: statusDiv});
    }
  },
  
  displayResults(text, isError=false) {
    const resultsDiv = document.getElementById('aiAuditorResults');
    resultsDiv.classList.remove('hidden');
    
    let parsedText = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
    parsedText = parsedText.replace(/\n- /g, '<br>• ');
    parsedText = parsedText.replace(/\n/g, '<br>');
    
    resultsDiv.innerHTML = `<div class="p-3 rounded-lg ${isError ? 'bg-red-50 text-red-800 border border-red-200' : 'bg-[var(--card)] text-[var(--text)] border border-[var(--line)]'} text-[13px]">${parsedText}</div>`;
  }
};
