function skeletonTree(){
  const N=(id,kind,label)=>({id,kind,label,desc:'',gate:null,root:false,estado:'',origem:'',justificativa:'',classificacao:'',responsavel:'',prazo:'',status:'',causaRaizId:''});
  const nodes=[
    N('evt','evt','Evento topo'),
    N('imed','imediata','Causa imediata'),
    N('gate1','gate','OU'),
    N('hip','hipotese','HIPÓTESES'),
    N('fal','falha','FALHA DE PROJETO'),
    N('fat','fatores','FATORES HUMANOS'),
    N('fs1','fator_sub','ORGANIZACIONAL'),
    N('fs2','fator_sub','AMBIENTAL'),
    N('fs3','fator_sub','TECNOLÓGICO'),
    N('fs4','fator_sub','INDIVIDUAL')
  ];
  const E=(s,t,g)=>({id:'e_'+s+'_'+t,source:s,target:t,gate:g||''});
  const edges=[E('evt','imed'),E('imed','gate1'),E('gate1','hip','OU'),E('gate1','fal','OU'),E('gate1','fat','OU'),
    E('fat','fs1'),E('fat','fs2'),E('fat','fs3'),E('fat','fs4')];
  return {nodes,edges};
}
