/* v6.7.8 (R-04): esta migracao existia SO' dentro de load(). normalizeImportedStudy()
   (bloco b12) fazia uma versao reduzida, entao um estudo IMPORTADO entrava sem
   linkedRefIds, sem os campos de eficacia das acoes, sem conclusion, sem os flags
   da comissao e — o pior — sem classificacaoV2. Agora ha' uma fonte unica.
   Declaracao de funcao (hoisted) e sem dependencia de const de topo: pode ser
   chamada por load(), que roda muito antes das constantes da matriz. */
/* v6.7.8 (S-04): 'why_'+Date.now() colidia quando dois estudos nasciam no
   mesmo milissegundo (duplicar com duplo clique) e o segundo sobrescrevia o
   primeiro em toda busca por id. Contador monotonico + aleatorio. */
function novoIdWhy(){window.__faciuIdSeq=(window.__faciuIdSeq||0)+1;return 'why_'+Date.now().toString(36)+'_'+window.__faciuIdSeq.toString(36)+Math.random().toString(36).slice(2,5);}
function migrarEstudo(data){
  if(!data||typeof data!=='object'||!data.tree||!Array.isArray(data.tree.nodes))return data;
  if(!Array.isArray(data.tree.edges))data.tree.edges=[];
  data.tree.nodes.forEach(n=>{n.origem??='';n.justificativa??='';n.causaRaizId??='';n.estado??='';if(n.kind==='raiz')n.root=true;});
  data.audit??=[];data.whys=migrateLegacyWhys(Array.isArray(data.whys)?data.whys:[]);
  data.externalReferences??=[];data.chronology??=[];
  data.conclusion??={summary:'',contributors:'',roots:'',actions:'',limitations:'',references:'',generated:false};
  data.tree.nodes.forEach(n=>{n.confirmationCondition??='';n.pendingReferenceNote??='';if(!Array.isArray(n.linkedRefIds))n.linkedRefIds=[];if(n.kind==='acao'){n.actionType??='';n.effectivenessCriterion??='';n.verificationDate??='';n.verificationResponsible??='';n.implementationReference??='';n.effectivenessResult??='Pendente';n.effectivenessNotes??='';n.requiresNewAction??=false;n.complementaryAction??='';}});
  if(!Array.isArray(data.equipe))data.equipe=[];
  if(!data.commissionExceptions||typeof data.commissionExceptions!=='object')data.commissionExceptions={};
  data.equipe.forEach(m=>{m.areaRepresentative??=false;m.contractorRepresentative??=false;m.cipaRepresentative??=/CIPA|CIPLAT/i.test(m.func||'');m.technicalKnowledge??=false;m.rcaQualified??=(m.qual==='Atende');m.investigationManager??=/Gestor da investigação/i.test(m.func||'');m.commissionCoordinator??=/Coordenador/i.test(m.func||'')});
  data.triagem??={};
  /* v6.7.8 (R-05): classificacaoV2 presente porem malformada quebrava
     recalcClassification() em cs.overrideReason.trim() e cs.assessments.some().
     Saneia campo a campo em vez de descartar a avaliacao inteira. */
  const cs=data.classificacaoV2;
  if(cs&&typeof cs==='object'&&!Array.isArray(cs)){
    if(!Array.isArray(cs.assessments))cs.assessments=[];
    if(typeof cs.overrideReason!=='string')cs.overrideReason='';
    cs.matrixRevision??='07';
    if(cs.calculatedSeverity===undefined)cs.calculatedSeverity=null;
    if(cs.reviewedSeverity===undefined)cs.reviewedSeverity=null;
    if(cs.finalSeverity===undefined)cs.finalSeverity=null;
  }else{
    data.classificacaoV2={matrixRevision:'07',assessments:[],calculatedSeverity:null,reviewedSeverity:null,finalSeverity:Number(data.triagem?.sev)||null,overrideReason:'',legacy:!!data.triagem?.nivel};
  }
  data.step=Number(data.step)||1;
  data.versao=APP_VERSION;
  return data;
}

