async function newStudy() {
  const hasData = state && state.triagem && (state.triagem.cii || state.triagem.titulo);
  if (hasData && !confirm('Iniciar um novo estudo? O atual será substituído.')) return;
  
  store = new InvestigationStore(novoEstado());
  state = store.getState();
  seq = 1;
  save();
  if (cy) { cy.destroy(); cy = null; }
  hideStartScreen();
  renderAll();
  toast('Novo estudo criado (modelo padrão carregado).');
  
  const btn = document.getElementById('btnDiskSync');
  if (btn) await enableDiskSync(btn);
}
function resetTree(){ if(confirm('Restaurar a árvore para o modelo padrão? Os blocos atuais serão perdidos.')){ /* v6.7.8 (E-01): o conjunto de ids removidos e calculado ANTES de trocar a arvore. A versao anterior usava 'rm', que so existe em deleteSelected: lancava ReferenceError depois de ja ter apagado tree e whys e antes de save(), deixando o estado destruido em memoria e a tela congelada. */ const removidos=new Set(state.tree.nodes.map(n=>n.id)); const total=removidos.size; state.tree=skeletonTree(); state.whys=[]; (state.chronology||[]).forEach(c=>{ if(removidos.has(c.linkedNodeId)) c.linkedNodeId=''; }); audit('tree.reset',null,'Modelo padrão restaurado; '+total+' bloco(s) removido(s)',['tree','whys']);selectedId=null;save();cyFromState(); renderRaias(); refreshLinkSelectors(); toast('Modelo padrão restaurado.'); } }

