function helpDocumentUrl(){
  if(helpBlobUrl) return helpBlobUrl;
  const raw=atob(HELP_CENTER_B64), chunk=32768, parts=[];
  for(let i=0;i<raw.length;i+=chunk){const slice=raw.slice(i,i+chunk), bytes=new Uint8Array(slice.length);for(let j=0;j<slice.length;j++)bytes[j]=slice.charCodeAt(j);parts.push(bytes);}
  helpBlobUrl=URL.createObjectURL(new Blob(parts,{type:'text/html;charset=utf-8'})); return helpBlobUrl;
}
function openHelp(){
  helpReturnFocus=document.activeElement; const modal=document.getElementById('helpModal'), frame=document.getElementById('helpFrame');
  if(!frame.src) frame.src=helpDocumentUrl(); modal.hidden=false; document.body.classList.add('help-open'); lucide.createIcons();
  setTimeout(()=>document.getElementById('helpCloseBtn').focus(),0);
}
