function goStep(n){
  state.step=n; save();
  document.querySelectorAll('.step').forEach(s=>{ s.dataset.active=(s.dataset.step==n); s.dataset.done=(Number(s.dataset.step)<n); });
  document.querySelectorAll('.view').forEach(v=> v.dataset.active=(v.dataset.view==n));
  if(n==2){ ensureCy(); renderRaias(); refreshLinkSelectors(); renderWhys(); switchStructureTab(activeStructureTab||'tree'); if((activeStructureTab||'tree')==='tree')requestAnimationFrame(()=>cy?.resize()); }
  if(n==4) renderValidation();
  if(n==6) { renderStandaloneWhys(); }
  if(n==3) renderReport();
  lucide.createIcons(); window.scrollTo({top:0,behavior:'smooth'});
}

