function onTriage(){ syncTriage(); save(); }
function syncTriage(){
  const t=state.triagem;
  /* v6.7.8 (R-03): syncTriage() e' chamada por validationItems(), ou seja, uma
     LEITURA de validacao grava no estado. Quando o elemento nao esta no DOM,
     val() devolve '' e o valor gravado era apagado. Agora campo ausente e'
     campo nao tocado: validar deixou de poder destruir dado. */
  const put=(campo,id)=>{const e=document.getElementById(id); if(e) t[campo]=e.value;};
  put('cii','f_cii'); put('titulo','f_titulo'); put('ocorr','f_ocorr'); put('reg','f_reg');
  put('site','f_site'); put('local','f_local'); put('atividade','f_atividade'); put('pt','f_pt');
  put('regpor','f_regpor'); put('contratada','f_contratada'); put('descricao','f_descricao');
  const tp=document.querySelector('input[name=f_tipo]:checked'); if(tp) t.tipo=tp.value; else t.tipo=t.tipo||'real';
  put('dim','f_dim'); put('tipoc','f_tipoc'); put('criterio','f_criterio'); put('sev','f_sev');
  /* espelhos acompanham o id recem-lido, para o estado nunca ficar incoerente */
  try{ const c=selCat(), o=selOcc(), k=selCrit();
    if(c) t.dimLabel=c.label; if(o) t.tipocLabel=o.label; if(k) t.criterioLabel=k.text;
  }catch(e){ /* matriz indisponivel neste momento: espelhos ficam como estao */ }
  const evt=state.tree.nodes.find(n=>n.id==='evt'); if(evt) evt.desc = t.titulo||'';
}
