function renderValidation(){
  const items=validationItems(),done=items.filter(i=>i.ok).length,pending=items.filter(i=>!i.ok),pct=items.length?Math.round(done/items.length*100):100;
  document.getElementById('integRing').style.setProperty('--p',pct);document.getElementById('integPct').textContent=pct+'%';document.getElementById('validationDone').textContent=done;document.getElementById('validationPending').textContent=pending.length;document.getElementById('validationCount').textContent=done+' de '+items.length;document.getElementById('validationStatus').textContent=pct===100?'Estudo pronto para o relatório.':pct>=80?'Revisão final antes do relatório.':'Estudo incompleto. Revise os itens indicados.';
  const box=document.getElementById('checkList');box.innerHTML='';
  const groups=[...new Set(items.map(i=>i.group||'Outros'))];
  groups.forEach(groupName=>{const groupItems=items.filter(i=>(i.group||'Outros')===groupName);if(!groupItems.length)return;const section=document.createElement('div');section.className='validation-group';const h=document.createElement('h4');h.textContent=groupName+' ('+groupItems.filter(i=>i.ok).length+'/'+groupItems.length+')';section.appendChild(h);groupItems.forEach(it=>{const row=document.createElement('div');row.className='validation-row';const icon=document.createElement('i');icon.setAttribute('data-lucide',it.ok?'check-circle-2':'circle-dashed');icon.className='w-4 h-4 shrink-0';icon.style.color=it.ok?'#3C7A18':'#B5560F';const text=document.createElement('span');text.textContent=it.txt;if(!it.ok)text.style.fontWeight='700';row.append(icon,text);section.appendChild(row)});box.appendChild(section)});
  renderAttentionItems(items);renderRootActionTraceability();const warning=document.getElementById('reportWarning');warning.textContent=pending.length?pending.length+' item(ns) ainda precisam de atenção.':'';window.lucide&&window.lucide.createIcons();
}
function renderAttentionItems(items=validationItems()){
  const pending=items.filter(i=>!i.ok),detail=[...pending.filter(i=>i.id!=='tree.all-roots-actions'),...rootActionValidationItems()];const box=document.getElementById('attentionList');document.getElementById('attentionCount').textContent=detail.length+' item(ns)';box.innerHTML='';
  /* v6.6.0: resumo por criticidade. Duas celulas enquanto a taxonomia completa
     de severidade (item 5 do planejamento) nao existir. */
  if(detail.length){
   const nBloq=detail.filter(i=>i.severity==='blocking').length;
   const resumo=document.createElement('div');resumo.className='faciu-issue-summary';
   [['Bloqueios',nBloq],['Pendências',detail.length]].forEach(([rot,n])=>{
    const cel=document.createElement('div');
    const b=document.createElement('b');b.textContent=n;
    const s=document.createElement('span');s.textContent=rot;
    cel.append(b,s);resumo.append(cel);
   });
   box.append(resumo);
  }
  if(!detail.length){const ready=document.createElement('div');ready.className='validation-ready';ready.innerHTML='<i data-lucide="badge-check" class="w-8 h-8 mx-auto"></i><h4>Estudo pronto para o relatório</h4><p class="text-[12px] muted mt-1">Todos os critérios de verificação foram atendidos.</p>';box.appendChild(ready);return;}
  /* v6.6.0: lista fixa escondia grupos novos (Cronologia, Acoes). Ordem conhecida
     primeiro, o que nao estiver na lista vai para o fim em vez de sumir. */
  const ORDEM_GRUPOS=['Triagem','Classificação','Comissão','Cronologia','Hipóteses e evidências','Causas','Ações','5 Porquês','RIA','Estruturação'];
  const gruposPresentes=[...new Set(detail.map(i=>i.group).filter(Boolean))].sort((a,b)=>(ORDEM_GRUPOS.indexOf(a)+1||99)-(ORDEM_GRUPOS.indexOf(b)+1||99));
  gruposPresentes.forEach(group=>{const entries=detail.filter(i=>i.group===group);if(!entries.length)return;const title=document.createElement('div');title.className='attention-group-title';title.textContent=group+' · '+entries.length;box.appendChild(title);entries.sort((a,b)=>(a.severity==='blocking'?0:1)-(b.severity==='blocking'?0:1)).forEach(it=>{const row=document.createElement('article');row.className='attention-item '+it.severity;const ico=document.createElement('div');ico.className='attention-icon';ico.innerHTML='<i data-lucide="'+(it.severity==='blocking'?'octagon-alert':'circle-alert')+'" class="w-4 h-4"></i>';const content=document.createElement('div');const h=document.createElement('div');h.className='attention-title';h.textContent=it.title;const d=document.createElement('div');d.className='attention-description';d.textContent=it.description;const loc=document.createElement('div');loc.className='attention-location';loc.textContent=it.location;content.append(h,d,loc);const actions=document.createElement('div');actions.className='attention-actions';const btn=document.createElement('button');btn.type='button';btn.className='btn btn-ghost';btn.setAttribute('aria-label',it.actionLabel+': '+it.title);btn.innerHTML='<i data-lucide="pencil" class="w-4 h-4"></i> '+it.actionLabel;btn.addEventListener('click',()=>editValidationItem(it.id));actions.appendChild(btn);row.append(ico,content,actions);box.appendChild(row)})});
}
function renderRootActionTraceability(){const box=document.getElementById('rootActionTrace');if(!box)return;box.innerHTML='';const matrix=rootActionMatrix();if(!matrix.length){const p=document.createElement('p');p.className='muted text-sm';p.textContent='Nenhuma causa-raiz cadastrada.';box.appendChild(p);return;}matrix.forEach(({root,actions})=>{const row=document.createElement('div');row.className='trace-row '+(actions.length?'':'bad');const r=document.createElement('b');r.textContent=nodeCode(root)+' • '+root.label;const a=document.createElement('span');a.textContent=actions.length?actions.map(x=>nodeCode(x)+' • '+x.label).join(', '):'Nenhuma ação vinculada';const st=document.createElement('span');st.className='trace-status '+(actions.length?'ok':'bad');st.textContent=actions.length?'Atendida':'Precisa de atenção';row.append(r,a,st);box.appendChild(row)});}
function editValidationItem(itemId){const perRoot=rootActionValidationItems().find(i=>i.id===itemId);if(perRoot){createActionForRoot(perRoot.targetId,itemId);return;}const item=validationItems().find(i=>i.id===itemId);if(!item)return;if(item.targetType==='whys'){validationReturn={itemId,title:item.title};showCorrectionBar(item.title);goStep(2);switchStructureTab('whys');setTimeout(()=>document.getElementById('whyModule')?.scrollIntoView({behavior:'smooth',block:'start'}),180);return;}if(item.targetType==='trace'){document.querySelector('.trace-panel')?.setAttribute('open','');document.querySelector('.trace-panel')?.scrollIntoView({behavior:'smooth',block:'start'});return;}validationReturn={itemId,title:item.title};showCorrectionBar(item.title);goStep(item.step);setTimeout(()=>focusValidationTarget(item),180);}
function focusValidationTarget(item){
 /* v6.6.0: destinos especificos, item 11.3 do planejamento. Antes, tudo que nao
    fosse campo caia no ramo da arvore e rolava para #cy. */
 if(item.targetType==='chronology'){
  switchStructureTab('chronology');
  setTimeout(()=>{
   const alvo=[...document.querySelectorAll('#chronologyList .chronology-item')].find(c=>c.dataset.chronId===item.targetId);
   (alvo||document.getElementById('chronologyList'))?.scrollIntoView({behavior:'smooth',block:'center'});
   if(alvo){alvo.classList.add('correction-target');setTimeout(()=>alvo.classList.remove('correction-target'),2800);}
  },180);
  return;
 }
 if(item.targetType==='tree'){switchStructureTab('lanes');}
 if(item.targetType==='field'){const el=document.getElementById(item.targetId);if(!el)return;el.scrollIntoView({behavior:'smooth',block:'center'});el.focus();el.classList.add('correction-target');setTimeout(()=>el.classList.remove('correction-target'),2800);return;}ensureCy();const id=item.targetId||(item.edgeId?state.tree.edges.find(e=>e.id===item.edgeId)?.target:'');if(id&&node(id)){selectNode(id);cy?.$('#'+cssid(id)).select();cy?.animate({center:{eles:cy.$('#'+cssid(id))},zoom:Math.max(cy.zoom(),.9)},{duration:300});}document.getElementById('cy')?.scrollIntoView({behavior:'smooth',block:'center'});}
