function createActionForRoot(rootId,itemId=''){const root=node(rootId);if(!root||root.kind!=='raiz'){toast('Causa-raiz não localizada.');return;}const id='n'+(seq++)+'_'+Date.now().toString().slice(-4),nn={id,kind:'acao',label:'Nova ação',desc:'',gate:null,root:false,estado:'',origem:'',justificativa:'',classificacao:'',responsavel:'',prazo:'',status:'Pendente',causaRaizId:root.id,causaRaizIds:[root.id]};state.tree.nodes.push(nn);state.tree.edges.push({id:'e_'+root.id+'_'+id,source:root.id,target:id,gate:''});audit('node.created',id,'Ação criada para '+root.label,['kind','causaRaizId']);save();validationReturn={itemId,title:'Criar ação para '+nodeCode(root)};showCorrectionBar(validationReturn.title);goStep(2);setTimeout(()=>{selectNode(id);openNodeModal(id,document.activeElement)},180);}
