function brandHeader(pdf,titulo,sub){
  const W=pdf.internal.pageSize.getWidth();
  pdf.setFillColor(34,28,79); pdf.rect(0,0,W,50,'F');
  pdf.setFillColor(198,230,0); pdf.rect(0,50,W,3,'F');
  pdf.setTextColor(198,230,0); pdf.setFont('helvetica','bold'); pdf.setFontSize(15); pdf.text('BRAVA',40,30);
  pdf.setTextColor(255,255,255); pdf.setFontSize(12); pdf.text(titulo,105,26);
  if(sub){ pdf.setFontSize(8); pdf.setTextColor(210,210,220); pdf.text(sub,105,38); }
}
function brandFooter(pdf,page,total){
  const W=pdf.internal.pageSize.getWidth(), H=pdf.internal.pageSize.getHeight();
  pdf.setDrawColor(220); pdf.line(40,H-26,W-40,H-26);
  pdf.setTextColor(120); pdf.setFontSize(7.5); pdf.setFont('helvetica','normal');
  pdf.text('FACIU • App v'+APP_VERSION,40,H-15);
  pdf.text('Referência: PG-CORP-SMS-015 - Classificação, Investigação e Tratamento de Incidentes - Rev. 07',W/2,H-15,{align:'center'});
  pdf.text('Página '+page+' de '+total,W-40,H-15,{align:'right'});
}
async function exportPDF(){
  renderReport();
  const { jsPDF }=window.jspdf||{}; if(!jsPDF){ toast('Biblioteca de PDF indisponível (sem internet?).'); return; }
  toast('Gerando PDF…');
  const t=state.triagem;
  // Página 1 — Árvore (paisagem)
  const pdf=new jsPDF('l','pt','a4');
  const LW=pdf.internal.pageSize.getWidth(), LH=pdf.internal.pageSize.getHeight();
  brandHeader(pdf,'Árvore de Investigação de Causas','CII: '+(t.cii||'—')+'  |  Site: '+(t.site||'—')+'  |  Local: '+(t.local||'—'));
  if(cy){ try{
    const treePng=cy.png({full:true,scale:2,bg:'#FFFFFF'}); const im=new Image(); im.src=treePng;
    await new Promise(r=>{ im.onload=r; im.onerror=r; });
    const availW=LW-80, availH=LH-100; let w=availW, h=im.height*w/im.width; if(h>availH){ h=availH; w=im.width*h/im.height; }
    pdf.addImage(treePng,'PNG',(LW-w)/2,70,w,h);
  }catch(e){ pdf.setTextColor(120); pdf.text('Árvore indisponível para exportação.',40,90); } }
  brandFooter(pdf,1,3);
  // Páginas 2-3 — Relatório (retrato), fatiado
  const area=document.getElementById('reportArea');
  const canvas=await html2canvas(area,{scale:2,backgroundColor:'#FFFFFF'});
  pdf.addPage('a4','p');
  const PW=pdf.internal.pageSize.getWidth(), PH=pdf.internal.pageSize.getHeight();
  const imgW=PW-80, ratio=canvas.width/imgW; const pageContentH=PH-100; let sy=0, page=2;
  while(sy<canvas.height){
    if(page>2){ pdf.addPage('a4','p'); }
    brandHeader(pdf,'Relatório de Investigação de Causas','CII '+(t.cii||'—')+' • '+(t.titulo||'—'));
    const sliceH=Math.min(pageContentH*ratio, canvas.height-sy);
    const sc=document.createElement('canvas'); sc.width=canvas.width; sc.height=sliceH;
    sc.getContext('2d').drawImage(canvas,0,sy,canvas.width,sliceH,0,0,canvas.width,sliceH);
    pdf.addImage(sc.toDataURL('image/png'),'PNG',40,70,imgW,sliceH/ratio);
    brandFooter(pdf,page,Math.max(3,page)); sy+=sliceH; page++;
  }
  pdf.save((t.titulo||'Relatorio-Investigacao')+'.pdf'); toast('PDF gerado no modelo.');
}

/* ===== UTILS / BOOT ===== */
function esc(s){ return (s==null?'':String(s)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function sanitizeHTML(str){
  if(!str) return '';
  const doc = new DOMParser().parseFromString(str, 'text/html');
  doc.body.querySelectorAll('script, style, iframe, object, embed, link, meta, base').forEach(t=>t.remove());
  doc.body.querySelectorAll('*').forEach(el=>{
    Array.from(el.attributes).forEach(attr=>{
      if(attr.name.toLowerCase().startsWith('on')) el.removeAttribute(attr.name);
      if((attr.name.toLowerCase()==='href'||attr.name.toLowerCase()==='src') && attr.value.toLowerCase().startsWith('javascript:')) el.removeAttribute(attr.name);
    });
  });
  return doc.body.innerHTML;
}
function trunc(s,n){ s=s||''; return s.length>n?s.slice(0,n-1)+'…':s; }
