  set('f_atividade',t.atividade);set('f_pt',t.pt);set('f_regpor',t.regpor);set('f_contratada',t.contratada);set('f_descricao',t.descricao);
  set('f_dim',t.dim);set('f_tipoc',t.tipoc);set('f_criterio',t.criterio);set('f_sev',t.sev);
